package com.trampolim.api.career;
import java.util.*;import java.time.*;import com.trampolim.api.security.PlatformAccess;import static com.trampolim.api.radar.RadarModel.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@RestController @org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true") public class CareerCostController {
 private final JdbcTemplate jdbc;private final PlatformAccess access;public CareerCostController(@Qualifier("empresasJdbcTemplate")JdbcTemplate jdbc,PlatformAccess access){this.jdbc=jdbc;this.access=access;}
 public record Cost(long companyId,String month,long amountCents,String source){}
 @PostMapping("/api/admin/career/costs")@org.springframework.transaction.annotation.Transactional("empresasTransactionManager")public Map<String,Object> save(@AuthenticationPrincipal String email,@RequestBody Cost input){if(!access.isSuperAdmin(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(input==null||input.companyId()<1||input.amountCents()<0||input.amountCents()>100000000000L||text(input.source(),500).length()<10)bad("Informe empresa, mês, valor em centavos e origem verificável do custo.");YearMonth month;try{month=YearMonth.parse(input.month());if(month.isAfter(YearMonth.now()))throw new IllegalArgumentException();}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Mês inválido ou futuro.");}if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM companies WHERE id=?)",Boolean.class,input.companyId())))throw new ResponseStatusException(HttpStatus.NOT_FOUND);jdbc.update("INSERT INTO company_operating_costs(company_id,month,amount_cents,source,recorded_by) VALUES (?,?,?,?,?) ON CONFLICT(company_id,month) DO UPDATE SET amount_cents=EXCLUDED.amount_cents,source=EXCLUDED.source,recorded_by=EXCLUDED.recorded_by,updated_at=CURRENT_TIMESTAMP",input.companyId(),month.atDay(1),input.amountCents(),input.source().trim(),email);jdbc.update("INSERT INTO company_audit_events(company_id,event_type) VALUES (?,'CAREER_COST_RECORDED_BY_PLATFORM')",input.companyId());return Map.of("recorded",true,"paymentCreated",false);}
}
